{
     "title": "CSCI-549: Seminar in Languages and Tools - Orientation Companion",
     "learningObjectives": [
       "Define the four practice groups of the Secure Software Development Framework and their roles in secure development.",
       "Explain how cryptographic standards, modes of operation, and key management collectively support confidentiality, integrity, and authenticity.",
       "Apply security reasoning to identify assets, trust boundaries, and residual risk in software development contexts."
     ],
     "beats": [
       {
         "title": "Course Scope and Faculty Pilot Model",
         "claim": "CSCI-549 serves as a faculty pilot course to examine current topics in Languages and Tools without a fixed RIT syllabus.",
         "example": "Instructors design semester-specific content based on emerging industry tools and academic research.",
         "visualDirection": "Display a flowchart showing 'Faculty Proposal' -> 'Seminar Design' -> 'Cluster Classification (Languages/Tools or Security)' -> 'Contact Hours: Lecture 3'.",
         "sourceIds": ["rit-csci-549"]
       },
       {
         "title": "Cluster Classification System",
         "claim": "Course instances are classified into the Languages and Tools cluster, the Security cluster, or both clusters.",
         "example": "A course focusing on compiler design and debugging tools falls under Languages and Tools, while one emphasizing vulnerability scanning targets Security.",
         "visualDirection": "Show a Venn diagram with two overlapping circles labeled 'Languages and Tools' and 'Security', with a third region labeled 'Both Clusters' and a fourth labeled 'Languages and Tools Only'.",
         "sourceIds": ["rit-csci-549"]
       },
       {
         "title": "Secure Software Development Framework Overview",
         "claim": "The Secure Software Development Framework groups practices into four practice groups: Prepare the Organization, Protect the Software, Produce Well-Secured Software, and Respond toV",
         "example": "Prepare the Organization establishes people, processes, and technology for secure development, while Respond to Vulnerabilities identifies and remediates discovered weaknesses.",
         "visualDirection": "Create a four-step horizontal pipeline labeled 'Prepare', 'Protect', 'Produce', 'Respond', with each step containing a brief icon representing its core function.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Prepare the Organization Practice",
         "claim": "Prepare the Organization establishes people, processes, and technology for secure development.",
         "example": "Teams define security policies, train developers on secure coding standards, and select development environments before writing code.",
         "visualDirection": "Illustrate a checklist with three items: 'People Training', 'Process Documentation', 'Technology Configuration', each with a checkmark.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Protect the Software Practice",
         "claim": "Protect the Software prevents unauthorized access to code and development artifacts.",
         "example": "Repositories use role-based access control, and source code repositories restrict commits to verified developers only.",
         "visualDirection": "Draw a locked vault icon with a key labeled 'Access Control' and a shield labeled 'Artifact Protection' surrounding a code repository symbol.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Produce Well-Secured Software Practice",
         "claim": "Produce Well-Secured Software addresses security requirements, design, verification, and release.",
         "example": "Developers integrate security requirements into design documents, run automated verification tests, and sign off on secure releases.",
         "visualDirection": "Show a document with sections labeled 'Security Requirements', 'Design Review', 'Verification Results', and 'Release Approval' in a sequential layout.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Respond to Vulnerabilities Practice",
         "claim": "Respond to Vulnerabilities identifies, analyzes, remediates, and learns from discovered weaknesses.",
         "example": "When a vulnerability scanner flags a flaw, the team patches the code, updates documentation, and trains staff on the new security protocol.",
         "visualDirection": "Create a cycle diagram with arrows connecting 'Identify', 'Analyze', 'Remediate', and 'Learn', forming a continuous improvement loop.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Cryptographic Standards and Confidentiality",
         "claim": "Cryptographic standards define approved algorithms and parameters that support confidentiality when keys and modes are used correctly.",
         "example": "AES-256 encryption protects sensitive data in transit, provided symmetric keys are managed securely and the correct mode of operation is applied.",
         "visualDirection": "Display a padlock icon with a key labeled 'Key Management' and a gear labeled 'Mode of Operation' above a document labeled 'Confidential Data'.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Integrity, Authenticity, and Key Management",
         "claim": "Message authentication and digital signatures address integrity and authenticity in different ways, while key management covers generation, distribution, storage, use, rotation,rev",
         "example": "Digital signatures verify that a code commit originated from an authorized developer, and key rotation ensures old cryptographic keys are securely destroyed after use.",
         "visualDirection": "Show a document with a signature stamp labeled 'Digital Signature' and a calendar icon labeled 'Key Rotation' next to a trash can labeled 'Secure Destruction'.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Modes of Operation and Side Channels",
         "claim": "Modes of operation define how a primitive processes data larger than one block, and security depends on the complete protocol and implementation, not only an algorithm name.",
         "example": "Using CBC mode with a fixed IV compromises security, whereas GCM mode with a random nonce ensures proper data processing and protection against side-channel attacks.",
         "visualDirection": "Illustrate two data blocks being processed: one with a flawed 'Fixed IV' warning label, and another with a 'Random Nonce' shield icon, connected by a flow arrow labeled 'Mode of Operation'.",
         "sourceIds": ["nist-cryptographic-standards"]
       }
     ]
   }
